//! Puerto's runtime core: the domain types every project generated by
//! [Puerto](https://github.com/Guuri11/Puerto) shares, whatever its entities and adapters — paged
//! lists, the repository error, domain events with the ports their transports implement, and the
//! mail ports, and the auth port.
//!
//! No driver, no runtime, no I/O: a project's domain layer depends on it (ADR-0017, ADR-0018).

pub mod auth;
pub mod events;
pub mod mail;
pub mod pagination;
pub mod repository_error;

pub use auth::{AuthError, Authenticator, Principal};
pub use events::{DecodeError, DomainEvent, EventEnvelope, EventHandler, HandlerOutcome};
pub use pagination::{DEFAULT_PAGE_LIMIT, MAX_PAGE_LIMIT, Page, PageRequest};
pub use repository_error::RepositoryError;
